//! How each platform answers Java's character questions, generated by running
//! `tools/JavaChars.java` there (`tools/generate-char-tables.sh`).
//!
//! Kotlin asks `java.lang.Character`, which on Android is ICU and differs from a computer's JVM for
//! some characters: Android's `isLowerCase` and `isUpperCase` are only the categories Ll and Lu
//! (not ª or Ⅻ), its regex `\s` is all of Unicode's White_Space rather than ASCII's, and it counts
//! U+180E as whitespace. So the library built for Android answers as Android does, and the one
//! built for a computer, which the JVM tests load, as the JVM does.

#[cfg(any(test, target_os = "android"))]
pub(crate) mod android;
#[cfg(any(test, not(target_os = "android")))]
pub(crate) mod jvm;

#[cfg(target_os = "android")]
pub(crate) use android::TABLES;
#[cfg(not(target_os = "android"))]
pub(crate) use jvm::TABLES;

/// One platform's answers for every code point.
#[derive(Debug)]
pub(crate) struct Tables {
    /// Where each run of code points with the same flags starts, ascending from 0.
    pub flag_starts: &'static [u32],
    /// Each run's flags: `LETTER`, `DIGIT` and so on in lib.rs.
    pub flags: &'static [u16],
    /// The code points whose `Character.toUpperCase` differs from themselves, ascending.
    pub upper_from: &'static [u32],
    /// Their upper case, in the same order.
    pub upper_to: &'static [u32],
    /// The code points whose `Character.toLowerCase` differs from themselves, ascending.
    pub lower_from: &'static [u32],
    /// Their lower case, in the same order.
    pub lower_to: &'static [u32],
    /// The code points whose `String.toUpperCase`, on its own, isn't their simple upper case
    /// (ß becomes SS), ascending.
    pub full_upper_from: &'static [u32],
    /// Those upper cases' UTF-16 units, in the same order.
    pub full_upper_to: &'static [&'static [u16]],
    /// The same for `String.toLowerCase`: only İ, which becomes i and a combining dot.
    pub full_lower_from: &'static [u32],
    /// Those lower cases' UTF-16 units, in the same order.
    pub full_lower_to: &'static [&'static [u16]],
    /// Where each run of decimal digits 0 to 9 (`Character.digit(cp, 10)`) starts, ascending.
    pub digit_zeros: &'static [u32],
    /// The BMP units whose canonical decomposition (NFD) starts with another code point, except
    /// Hangul syllables, ascending.
    pub decomposed_from: &'static [u32],
    /// That code point, in the same order.
    pub decomposed_to: &'static [u32],
}

impl Tables {
    pub fn flags(&self, code_point: u32) -> u16 {
        // The first run starts at 0, so every code point is in one.
        let run = self
            .flag_starts
            .partition_point(|&start| start <= code_point)
            - 1;
        self.flags[run]
    }

    pub fn upper(&self, code_point: u32) -> u32 {
        map(code_point, self.upper_from, self.upper_to)
    }

    pub fn lower(&self, code_point: u32) -> u32 {
        map(code_point, self.lower_from, self.lower_to)
    }

    pub fn full_upper(&self, code_point: u32) -> Option<&'static [u16]> {
        let i = self.full_upper_from.binary_search(&code_point).ok()?;
        Some(self.full_upper_to[i])
    }

    pub fn full_lower(&self, code_point: u32) -> Option<&'static [u16]> {
        let i = self.full_lower_from.binary_search(&code_point).ok()?;
        Some(self.full_lower_to[i])
    }

    /// `Character.digit(code_point, 10)`, or `None` where that is -1.
    pub fn digit(&self, code_point: u32) -> Option<u8> {
        let run = self.digit_zeros.partition_point(|&zero| zero <= code_point);
        let zero = self.digit_zeros[run.checked_sub(1)?];
        u8::try_from(code_point - zero)
            .ok()
            .filter(|&value| value <= 9)
    }

    pub fn decomposed(&self, unit: u16) -> u32 {
        map(u32::from(unit), self.decomposed_from, self.decomposed_to)
    }
}

fn map(code_point: u32, from: &[u32], to: &[u32]) -> u32 {
    from.binary_search(&code_point)
        .map_or(code_point, |i| to[i])
}
